      "hash": "d41e8c0de5bd6baac8e64c1cd9f79ae7e2b5ea0f117e3a7b0f88ca142a1214db",
      "content": "export interface Actor {\n  id: string;\n  role: 'client' | 'freelancer';\n}\n\nexport interface Milestone {\n  id: string;\n  ownerClientId: string;\n  status: 'active' | 'archived';\n}\n\nexport function canApproveMilestone(actor: Actor, _milestone: Milestone): boolean {\n  // Disclosed teaching seed: ownership is intentionally omitted.\n  return actor.role === 'client' && actor.id === _milestone.ownerClientId;\n}\n"
